const parse = (value) => {
  if (typeof value !== 'string') return value ?? {};
  try { return JSON.parse(value); } catch { return {}; }
};
const clean = (value, limit) => String(value ?? '').replace(/[\u0000-\u001f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, limit);
const multiline = (value, limit) => String(value ?? '').replace(/\u0000/g, '').trim().slice(0, limit);
const input = items[0]?.json ?? {};
const body = parse(input.body ?? input);
const repo = clean(body.repo, 500);
const nextStep = clean(body.nextStep, 800);
if (!repo || !nextStep) throw new Error('repo and nextStep are required');
const capsule = {
  id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
  capturedAt: new Date().toISOString(),
  repo,
  repoName: clean(body.repoName, 120) || repo.split('/').filter(Boolean).at(-1),
  branch: clean(body.branch, 200) || 'detached-or-unknown',
  head: clean(body.head, 200),
  status: multiline(body.status, 4000),
  diffStat: multiline(body.diffStat, 2000),
  failedCommand: clean(body.failedCommand, 1000),
  nextStep,
};
const state = $getWorkflowStaticData('global');
const capsules = Array.isArray(state.capsules) ? state.capsules : [];
state.capsules = [capsule, ...capsules.filter((entry) => entry.repo !== repo)].slice(0, 25);
return [];

const input = items[0]?.json ?? {};
const query = input.query ?? {};
const wanted = String(query.repo ?? '').trim().toLowerCase();
const wantedName = wanted.split('/').filter(Boolean).at(-1) ?? '';
const state = $getWorkflowStaticData('global');
const capsules = Array.isArray(state.capsules) ? state.capsules : [];
const capsule = wanted
  ? capsules.find((entry) => String(entry.repo).toLowerCase() === wanted || String(entry.repoName).toLowerCase() === wanted || String(entry.repoName).toLowerCase() === wantedName)
  : capsules[0];
if (!capsule) return [{ json: { ok: false, error: 'No matching restart capsule.' } }];
return [{ json: { ok: true, capsule } }];
